import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DEqXEGcv.js";const k=JSON.parse('{"title":"Storage Backends","description":"","frontmatter":{},"headers":[],"relativePath":"server/storage-backends.md","filePath":"server/storage-backends.md"}'),n={name:"server/storage-backends.md"};function d(o,e,r,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="storage-backends" tabindex="-1">Storage Backends <a class="header-anchor" href="#storage-backends" aria-label="Permalink to &quot;Storage Backends&quot;">​</a></h1><p>The SMQL server supports two storage backends. The backend is selected at startup with the <code>--storage</code> / <code>-s</code> flag.</p><h2 id="quick-comparison" tabindex="-1">Quick Comparison <a class="header-anchor" href="#quick-comparison" aria-label="Permalink to &quot;Quick Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Memory</th><th>RocksDB</th></tr></thead><tbody><tr><td>Persistence</td><td>None -- data lost on restart</td><td>Persistent to disk</td></tr><tr><td>Feature flag</td><td>None (always available)</td><td>Requires <code>rocksdb</code> feature</td></tr><tr><td>Performance</td><td>Fastest (DashMap)</td><td>Fast (LSM-tree, memory-mapped)</td></tr><tr><td>Concurrency</td><td>DashMap lock-free reads</td><td>RocksDB native concurrency</td></tr><tr><td>Use case</td><td>Development, testing, demos</td><td>Production, data durability</td></tr><tr><td>Startup</td><td>Instant</td><td>Opens/creates database directory</td></tr></tbody></table><h2 id="memory-backend-default" tabindex="-1">Memory Backend (default) <a class="header-anchor" href="#memory-backend-default" aria-label="Permalink to &quot;Memory Backend (default)&quot;">​</a></h2><p>The memory backend stores all instances, trails, and indexes in <code>DashMap</code> concurrent hash maps. It requires no configuration and is always available.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --storage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span></span></code></pre></div><p>This is the default when <code>--storage</code> is omitted:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Data is lost when the process exits. This backend is ideal for:</p><ul><li>Local development and experimentation</li><li>Automated tests</li><li>Demos and prototyping</li><li>Ephemeral workloads where persistence is not needed</li></ul><h2 id="rocksdb-backend" tabindex="-1">RocksDB Backend <a class="header-anchor" href="#rocksdb-backend" aria-label="Permalink to &quot;RocksDB Backend&quot;">​</a></h2><p>The RocksDB backend provides persistent, crash-safe storage backed by Facebook&#39;s <a href="https://rocksdb.org/" target="_blank" rel="noreferrer">RocksDB</a> embedded key-value store.</p><h3 id="enabling-rocksdb" tabindex="-1">Enabling RocksDB <a class="header-anchor" href="#enabling-rocksdb" aria-label="Permalink to &quot;Enabling RocksDB&quot;">​</a></h3><p>RocksDB is behind a Cargo feature flag. You must compile with the feature enabled:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the CLI with RocksDB support</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smql-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rocksdb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the server crate with RocksDB support</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smql-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rocksdb</span></span></code></pre></div><p>If you attempt to use a filesystem path for storage without the feature flag, the CLI exits with an error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RocksDB storage requested (&#39;./data&#39;) but the &#39;rocksdb&#39; feature is not enabled.</span></span>
<span class="line"><span>Rebuild with: cargo build --features rocksdb</span></span></code></pre></div><h3 id="starting-with-rocksdb" tabindex="-1">Starting with RocksDB <a class="header-anchor" href="#starting-with-rocksdb" aria-label="Permalink to &quot;Starting with RocksDB&quot;">​</a></h3><p>Pass a filesystem path instead of <code>memory</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create or open a RocksDB database at ./data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --storage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Absolute path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --storage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/smql/production</span></span></code></pre></div><p>The directory is created automatically if it does not exist.</p><h3 id="column-families" tabindex="-1">Column Families <a class="header-anchor" href="#column-families" aria-label="Permalink to &quot;Column Families&quot;">​</a></h3><p>RocksDB organizes data into six column families, each serving a specific index or data type:</p><table tabindex="0"><thead><tr><th>Column Family</th><th>Key Format</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>instances</code></td><td><code>{instance_id}</code></td><td>Serialized <code>Instance</code> (JSON)</td><td>Primary instance store</td></tr><tr><td><code>state_index</code></td><td><code>{machine}\\x00{state}\\x00{instance_id}</code></td><td><code>&quot;&quot;</code> (empty)</td><td>Find instances by machine + state</td></tr><tr><td><code>machine_index</code></td><td><code>{machine}\\x00{instance_id}</code></td><td><code>&quot;&quot;</code> (empty)</td><td>Find all instances of a machine</td></tr><tr><td><code>trails</code></td><td><code>{instance_id}\\x00{sequence:08}</code></td><td>Serialized <code>TrailEntry</code> (JSON)</td><td>Audit trail entries</td></tr><tr><td><code>parent_index</code></td><td><code>{parent_id}\\x00{child_id}</code></td><td><code>&quot;&quot;</code> (empty)</td><td>Parent-child composition lookup</td></tr><tr><td><code>id_index</code></td><td><code>{instance_id}</code></td><td><code>{machine}</code></td><td>Reverse lookup: ID to machine name</td></tr></tbody></table><p>Keys use <code>\\x00</code> (NUL byte) as the separator in composite keys. This ensures correct lexicographic ordering and clean prefix scans.</p><h3 id="atomic-operations" tabindex="-1">Atomic Operations <a class="header-anchor" href="#atomic-operations" aria-label="Permalink to &quot;Atomic Operations&quot;">​</a></h3><p>Multi-write operations (transitions that update instance + trail + indexes) use RocksDB <code>WriteBatch</code> for atomicity. Either all writes succeed or none do. This applies to:</p><ul><li>Spawn (instance + trail entry + all index entries)</li><li>Transition (instance update + trail entry + index updates)</li><li>Delete (instance + trail entries + all index entries)</li><li>Schema migration (bulk instance state updates)</li></ul><h3 id="data-serialization" tabindex="-1">Data Serialization <a class="header-anchor" href="#data-serialization" aria-label="Permalink to &quot;Data Serialization&quot;">​</a></h3><p>All values are serialized as JSON using <code>serde_json</code>. Keys are plain UTF-8 strings with NUL separators.</p><h3 id="range-queries" tabindex="-1">Range Queries <a class="header-anchor" href="#range-queries" aria-label="Permalink to &quot;Range Queries&quot;">​</a></h3><p>Index lookups (e.g., &quot;find all instances of SupportTicket in state open&quot;) use RocksDB range iteration with upper-bound options rather than prefix iterators. For a prefix like <code>SupportTicket\\x00open\\x00</code>, the iterator scans from that key up to <code>SupportTicket\\x00open\\x01</code> (the next byte after NUL).</p><h3 id="data-directory-structure" tabindex="-1">Data Directory Structure <a class="header-anchor" href="#data-directory-structure" aria-label="Permalink to &quot;Data Directory Structure&quot;">​</a></h3><p>RocksDB manages its own file layout inside the data directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./data/</span></span>
<span class="line"><span>  CURRENT</span></span>
<span class="line"><span>  IDENTITY</span></span>
<span class="line"><span>  LOCK</span></span>
<span class="line"><span>  LOG</span></span>
<span class="line"><span>  MANIFEST-000001</span></span>
<span class="line"><span>  OPTIONS-000001</span></span>
<span class="line"><span>  000001.sst</span></span>
<span class="line"><span>  000002.sst</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>Do not modify these files manually. Back up the entire directory if you need a snapshot.</p><h2 id="switching-between-backends" tabindex="-1">Switching Between Backends <a class="header-anchor" href="#switching-between-backends" aria-label="Permalink to &quot;Switching Between Backends&quot;">​</a></h2><p>The memory and RocksDB backends use the same <code>Storage</code> trait interface. Machines must be redefined after switching backends since machine definitions live in the in-memory catalog (not in storage).</p><p>A typical production workflow:</p><ol><li>Develop with <code>--storage memory</code> for fast iteration.</li><li>Deploy with <code>--storage /var/lib/smql/data</code> for durability.</li><li>Define machines on startup (e.g., via <code>smql run machines.smql</code> or through the API).</li></ol>`,41)])])}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
